def _clean(number):
    return number.replace(" ", "").replace("-", "")


def is_valid(number):
    try:
        s = _clean(number)
    except AttributeError:
        return False
    if len(s) < 2 or not s.isdigit():
        return False
    total = 0
    for i, ch in enumerate(reversed(s)):
        d = ord(ch) - 48
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0


def check_digit(partial):
    if not isinstance(partial, str):
        raise ValueError("partial must be a string of digits")
    s = _clean(partial)
    if len(s) < 1 or not s.isdigit():
        raise ValueError("partial must be one or more digits")
    total = 0
    for i, ch in enumerate(reversed(s)):
        d = ord(ch) - 48
        if i % 2 == 0:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return str((10 - (total % 10)) % 10)
